queries.metadata:
query MerchantActiveCoverageMetadata20260908($after: String) {
  shop { id name myshopifyDomain currencyCode }
  activeProducts: productsCount(query: "status:active", limit: null) { count precision }
  shopLocales(published: true) { locale name primary published }
  publications(first: 20, after: $after, catalogType: APP) {
    nodes {
      id
      catalog {
        id title status
        ... on AppCatalog {
          apps(first: 5) {
            nodes { id title handle }
            pageInfo { hasNextPage endCursor }
          }
        }
      }
    }
    pageInfo { hasNextPage endCursor }
  }
}

queries.products:
query MerchantAllActiveCoveragePage20260908($after: String, $onlinePublication: ID!, $googlePublication: ID!) {
  products(first: 200, after: $after, query: "status:active", sortKey: ID) {
    nodes {
      id status
      variantsCount { count precision }
      onlineStorePublished: publishedOnPublication(publicationId: $onlinePublication)
      googlePublished: publishedOnPublication(publicationId: $googlePublication)
    }
    pageInfo { hasNextPage endCursor }
  }
}
